import time
from enum import Enum

class State(Enum):
    CLOSED = "closed"        # normal: calls pass through
    OPEN = "open"            # tripped: calls fail immediately
    HALF_OPEN = "half_open"  # probing: one trial call allowed

class CircuitBreaker:
    def __init__(self, failure_threshold=5,
                 recovery_timeout=30, window=60):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.window = window
        self.state = State.CLOSED
        self.failures = 0
        self.opened_at = None

    def call(self, fn, *args, fallback=None, **kwargs):
        if self.state == State.OPEN:
            if time.time() - self.opened_at >= self.recovery_timeout:
                self.state = State.HALF_OPEN
            else:
                # Fail fast — do NOT call downstream
                return fallback

        try:
            result = fn(*args, **kwargs)
            self._on_success()
            return result
        except Exception as exc:
            self._on_failure()
            if fallback is not None:
                return fallback
            raise

    def _on_success(self):
        self.failures = 0
        self.state = State.CLOSED

    def _on_failure(self):
        self.failures += 1
        if self.failures >= self.failure_threshold:
            self.state = State.OPEN
            self.opened_at = time.time()

# Limit to 100 requests/second per IP, burst of 20
limit_req_zone $binary_remote_addr zone=api:10m rate=100r/s;

location /api/ {
    limit_req zone=api burst=20 nodelay;
    proxy_pass http://backend;
}
